  --ai-left: 340px;

  /* --- 🩵发送按钮（打字时显示） --- */
  --send-width: 60px;
  --send-height: 60px;
  --send-top: -7px;
  --send-left: 330px;

  /* --- 🩵打字时发送键左侧装饰图（仅装饰） --- */
  --dec-width: 35px;
