/* =========================================
   【修正】系统时间、系统提示框 (解决太长的问题)
========================================= */
.timestamp-custom,
.date-divider-custom,
.system-message-custom,
[class*="system-message"],
[class*="timestamp"],
[class*="date-divider"] {
