/* ========== 转账卡片 - 金额无类名保护版 ========== */

/* 1. 全局重置 */
.msg-transfer-card *,
.bubble-me-custom .msg-transfer-card *,
.bubble-them-custom .msg-transfer-card * {
  background-image: none !important;
  border: none !important;
