/* 3. 隐藏所有图标/装饰/小符号 */
.msg-transfer-card .transfer-icon,
.msg-transfer-card [class*="icon"],
.msg-transfer-card [class*="Icon"],
.msg-transfer-card [class*="banner"],
.msg-transfer-card [class*="decoration"],
.msg-transfer-card [class*="divider"],
.msg-transfer-card [class*="line"],
.msg-transfer-card [class*="bg"],
.msg-transfer-card img,
.msg-transfer-card svg,
