.voice-msg-me { max-width: 138px !important; }
.voice-msg-them { max-width: 138px !important; }
  /* 對方語音氣泡：時間戳文字 */
  .voice-msg-them .voice-duration,
  .voice-msg-them {
    color: #FFFFFF !important;
  }
  /* 對方語音氣泡：播放按鈕圖示（用 fill/color 對付 svg，用 filter 對付圖片型按鈕） */
  .voice-msg-them .voice-play-btn {
    color: #C8C8C8 !important;
    fill: #C8C8C8 !important;
  }
  .voice-msg-them .voice-play-btn svg,
  .voice-msg-them .voice-play-btn svg * {
    fill: #C8C8C8 !important;
    color: #C8C8C8 !important;
  }
  /* 我方語音氣泡：時間戳文字 */
  .voice-msg-me .voice-duration,
  .voice-msg-me {
    color: #111111 !important;
  }
  /* 我方語音氣泡：播放按鈕圖示（用 fill/color 對付 svg，用 filter 對付圖片型按鈕） */
  .voice-msg-me .voice-play-btn {
    color: #204525 !important;
    fill: #204525 !important;
  }
  .voice-msg-me .voice-play-btn svg,
  .voice-msg-me .voice-play-btn svg * {
    fill: #204525 !important;
    color: #204525 !important;
  }

/* ========== 核心：控件行強制壓扁，消除默認留白 ========== */
.voice-controls-row {
  position: relative;
  align-items: center;
  height: 26px !important;          /* 強制鎖定整行高度，比波形略高2px即可 */
  line-height: 1 !important;
  overflow: hidden !important;
  flex-shrink: 0 !important;
}

/* ========== 波形容器：消除上下隱性內邊距 ========== */
.voice-waveform {
  padding-top: 0 !important;
  padding-bottom: 0 !important;
  margin-top: 0 !important;
  margin-bottom: 0 !important;
  height: var(--voice-waveform-height) !important;
}

/* ========== 播放按鈕：縮小尺寸並居中 ========== */
.voice-play-btn {
  width: var(--voice-play-btn-size) !important;
  height: var(--voice-play-btn-size) !important;
  min-width: var(--voice-play-btn-size) !important;
  min-height: var(--voice-play-btn-size) !important;
  padding: 0 !important;
  margin: 0 !important;
  flex-shrink: 0 !important;
}

/* ========== 轉寫區（維持原設定不變） ========== */
.voice-transcription {
  width: 100% !important;
  text-align: left !important;
  flex-shrink: 0 !important;
  box-sizing: border-box !important;
  overflow-wrap: break-word;
}

/* ========== 透明功能按鈕 ========== */
.voice-download-btn {
  opacity: 0 !important;
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  pointer-events: auto !important;
  width: var(--voice-play-btn-size);
  height: var(--voice-play-btn-size);
  display: flex !important;
  z-index: 2;
}
.voice-transcription-toggle {
  opacity: 0 !important;
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 20px;
  pointer-events: auto !important;
  display: flex !important;
  padding: 0 !important;
  margin: 0 !important;
  z-index: 2;
  cursor: pointer;
}

/* ========== 翻譯區塊 ========== */
.msg-translation-wrapper {
  width: 100% !important;
  box-sizing: border-box !important;
  flex-shrink: 0 !important;
}
.msg-translation-content,
.msg-translation-detached-content {
  width: 100% !important;
  box-sizing: border-box !important;
  overflow-wrap: break-word !important;
  word-break: break-word !important;
}

/* ========== 氣泡小尾巴 ========== */
.voice-msg-me.voice-msg-first::after,
.voice-msg-me.voice-msg-single::after {
  content: '';
  position: absolute;
  right: -6px;
  top: 6px;                          /* 尾巴隨氣泡變扁往上微調 */
  width: 0;
  height: 0;
  border-top: 5px solid transparent;
  border-bottom: 5px solid transparent;
  border-left: 6px solid var(--bubble-me-bg, #86e886);
  z-index: 1;
}
.voice-msg-them.voice-msg-first::after,
.voice-msg-them.voice-msg-single::after {
  content: '';
  position: absolute;
  left: -6px;
  top: 6px;                          /* 尾巴隨氣泡變扁往上微調 */
  width: 0;
  height: 0;
  border-top: 5px solid transparent;
  border-bottom: 5px solid transparent;
  border-right: 6px solid var(--bubble-them-bg, #f5f5f5);
  z-index: 1;
}
/* ========== 強制非聚焦狀態下輸入文字為純白 ========== */
.input-box-custom,
.input-box-custom:not(:focus),
.input-box-custom:not(:focus-within) {
  color: #FFFFFF !important;
