  font-size: 10px !important;
  position: relative !important;
  top: auto !important;
  left: auto !important;
  z-index: 1 !important;
  white-space: nowrap !important;
}

/* 11. 但保留标题、状态、label 不受辅助文字影响（它们已经在上面单独控制了） */
/* 只隐藏卡片最外层、不在 amount 容器内、不在 label 容器内、无类名的元素 */
.msg-transfer-card > :not([class*="amount"]):not([class*="label"]):not([class]),
.msg-transfer-card > * > :not([class*="amount"]):not([class*="label"]):not([class]) {
  display: none !important;
  visibility: hidden !important;
  width: 0 !important;
  height: 0 !important;
  opacity: 0 !important;
}
