/* ==========================================
   10. 终极防御 (保护图片文字)
   ========================================== */
.nuo-forum-root .nuo-forum-post-media,
.nuo-forum-root .nuo-forum-post-media * {
    color: #1a1a1a !important;
    text-shadow: 0 0 4px rgba(255, 255, 255, 0.9) !important;
    opacity: 1 !important;
}

/* ==========================================
   补丁：恢复原生分享键并隐形映射到 SVG 图标by烧酒酒，请跟仿推特/𝕏论坛美化配套使用
   ========================================== */
/* 1. 解除底部数据容器的隐藏，改为全透明且不拦截点击 */
.nuo-forum-root .nuo-forum-post-metrics, 
.nuo-forum-root .nuo-forum-post-stats, 
.nuo-forum-root .nuo-forum-post-actions {
    display: block !important;
    position: absolute !important;
    bottom: 0 !important;
    left: 0 !important;
    width: 100% !important;
    height: 34px !important;
    opacity: 0 !important;
    z-index: 10 !important;
    pointer-events: none !important;
}

/* 2. 隐藏原生的点赞、回复等按钮*/
.nuo-forum-root .nuo-forum-post-metrics > *, 
.nuo-forum-root .nuo-forum-post-stats > *, 
.nuo-forum-root .nuo-forum-post-actions > * {
    display: none !important;
}

/* 3. 精准捕获分享键，并移动到 SVG 分享图标的正上方 */
.nuo-forum-root .nuo-forum-post-actions > *:last-child,
.nuo-forum-root .nuo-forum-post-metrics > *:last-child,
.nuo-forum-root .nuo-forum-post [class*="share"] {
    display: block !important;
    position: absolute !important;
    bottom: 0 !important;
    left: 320px !important; /* 精准对齐 SVG 分享图标的物理坐标 */
    width: 50px !important; /* 放大触控面积，防误触 */
    height: 34px !important;
    pointer-events: auto !important; /* 仅恢复分享键的点击功能 */
    cursor: pointer !important;
}

/* ==========================================
   补丁 2：分享卡片弹窗 纯正夜间模式（修复版）
   by烧酒酒，请搭配「仿推特/𝕏论坛 夜间版」使用

   ⚠️ 修复说明（by 砂砂）：
   旧版用 body > div:not(.nuo-forum-root) 做「越狱捕获」，
   但 body>div 匹配到的是整个 App 的根容器 #root，
   :not() 根本排不掉它 —— 于是 [class*="header"] /
   [class*="content"] / input 等通配规则打到了全 App，
   把聊天顶栏、主页背景一起改掉了。
   分享面板其实就在论坛容器内部（只是 position:fixed
   看起来像飘出去了），用正常选择器即可，无需越狱。
   ========================================== */

/* 1. 遮罩层 */
.nuo-forum-root .fanfic-modal-overlay {
    background: rgba(0, 0, 0, 0.6) !important;
}

/* 2. 弹窗面板本体（分享面板 / 询问对话框） */
.nuo-forum-root .fanfic-custom-panel,
.nuo-forum-root .fanfic-ask-dialog {
    background: #000000 !important;
    color: #e7e9ea !important;
    border: 1px solid #2f3336 !important;
    border-radius: 16px !important;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.25) !important;
}

/* 3. 弹窗头/身/脚 —— 透明继承面板底色，只改分割线 */
.nuo-forum-root .fanfic-custom-header,
.nuo-forum-root .fanfic-custom-body,
.nuo-forum-root .fanfic-custom-footer {
    background: transparent !important;
    color: #e7e9ea !important;
}
.nuo-forum-root .fanfic-custom-header {
    border-bottom: 1px solid #2f3336 !important;
}
.nuo-forum-root .fanfic-custom-footer {
    border-top: 1px solid #2f3336 !important;
}

/* 4. 弹窗内文字兜底（含被内联样式写死的 #888 / #999 摘要与副标题） */
.nuo-forum-root .fanfic-custom-panel,
.nuo-forum-root .fanfic-custom-panel div,
.nuo-forum-root .fanfic-custom-panel span,
.nuo-forum-root .fanfic-custom-panel p,
.nuo-forum-root .fanfic-ask-title,
.nuo-forum-root .fanfic-ask-text {
    color: #e7e9ea !important;
}
/* 次级信息稍微压暗，保留层次 */
.nuo-forum-root .fanfic-custom-panel .center-msg p,
.nuo-forum-root .fanfic-ask-text {
    opacity: 0.6 !important;
}

/* 5. 分享对象列表项：推特扁平分割线风格 */
.nuo-forum-root .forum-share-char-item {
    background: transparent !important;
    border-bottom: 1px solid #2f3336 !important;
    border-radius: 0 !important;
    margin: 0 !important;
    padding: 12px 4px !important;
    box-shadow: none !important;
}
.nuo-forum-root .forum-share-char-item:hover,
.nuo-forum-root .forum-share-char-item:active {
    background: rgba(231,233,234,0.08) !important;
}

/* 6. 角色/群组 分页按钮（内联样式用了 var(--ios-border)/var(--ios-blue)） */
.nuo-forum-root .fanfic-custom-body > div > button {
    border-color: #2f3336 !important;
}

/* 7. 弹窗内输入框：推特深灰胶囊 */
.nuo-forum-root .fanfic-custom-panel input,
.nuo-forum-root .fanfic-ask-dialog input,
.nuo-forum-root .fanfic-field input {
    background: #202327 !important;
    color: #e7e9ea !important;
    border: none !important;
    border-radius: 9999px !important;
    padding: 8px 16px !important;
}

/* 8. 关闭按钮 */
.nuo-forum-root .fanfic-custom-header .forum-icon-btn {
    background: transparent !important;
    color: #e7e9ea !important;
}

:root {
    /* --- X 纯正暗夜模式原生色 --- */
    --forum-page-bg: #000000;
    --forum-text: #e7e9ea;
    --forum-text-muted: #71767b;
    --forum-accent: #1d9bf0;
    --forum-divider: #2f3336;

    /* 抹除所有卡片感 */
    --forum-post-bg: #000000;
    --forum-post-radius: 0px;
    --forum-post-border: none;
    --forum-post-shadow: none;

    /* 顶栏与底栏 */
    --forum-chrome-bg: #000000;
    --forum-chrome-title-color: #e7e9ea;
    --forum-chrome-icon-color: #e7e9ea;
    --forum-chrome-nav-bg: #000000;
    --forum-chrome-nav-border: 1px solid var(--forum-divider);
    --forum-tabs-bg: #000000;
    --forum-tabs-border: 1px solid var(--forum-divider);

    /* 评论输入框 */
    --forum-comment-input-bar-bg: #000000;
    --forum-comment-input-bar-border: 1px solid #2f3336;
    --forum-comment-input-bg: #202327;
    --forum-comment-input-radius: 9999px;
    --forum-comment-input-color: #e7e9ea;

    /* 全局其他页面变量 */
    --forum-board-card-bg: #000000;
    --forum-board-card-border: 1px solid var(--forum-divider);
    --forum-board-hero-bg: #000000;
    --forum-board-icon-bg: #16181c;
    --forum-profile-bg: #000000;
    --forum-profile-header-bg: #000000;
    --forum-profile-stats-bg: #000000;
    --forum-message-item-bg: #000000;
    --forum-message-item-hover: #080808;

    --forum-font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

/* ==========================================
   1. 强制清理与隐藏杂项
   ========================================== */
.nuo-forum-root .nuo-forum-feed > div:not(:has(.nuo-forum-post)):not(:has(.nuo-forum-tabs)):not(.nuo-forum-tabs),
.nuo-forum-root [class*="tag"], .nuo-forum-root [class*="badge"], .nuo-forum-root [class*="level"],
.nuo-forum-root .nuo-forum-post-metrics, .nuo-forum-root .nuo-forum-post-stats, .nuo-forum-root .nuo-forum-post-actions {
    display: none !important;
}

/* ==========================================
   2. 顶栏与全局文字清晰化
   ========================================== */
.nuo-forum-root .nuo-forum-chrome-header, .nuo-forum-root .nuo-forum-chrome-title, .nuo-forum-root .nuo-forum-chrome-header * { color: #e7e9ea !important; fill: #e7e9ea !important; stroke: #e7e9ea !important; opacity: 1 !important; }
.nuo-forum-root .nuo-forum-post-detail-view *, .nuo-forum-root .nuo-forum-comment-content, .nuo-forum-root .nuo-forum-comment-author, .nuo-forum-root .nuo-forum-comments-header { color: #e7e9ea !important; opacity: 1 !important; text-shadow: none !important; }
.nuo-forum-root .nuo-forum-me *, .nuo-forum-root .nuo-forum-profile *, .nuo-forum-root .nuo-forum-messages-list *, .nuo-forum-root [class*="message"] *, .nuo-forum-root .nuo-forum-board-hero * { color: #e7e9ea !important; opacity: 1 !important; text-shadow: none !important; }
.nuo-forum-root .nuo-forum-boards-list * { color: #e7e9ea !important; opacity: 1 !important; }
.nuo-forum-root .nuo-forum-board-card svg, .nuo-forum-root .nuo-forum-board-card [class*="stat"], .nuo-forum-root .nuo-forum-board-card [class*="meta"], .nuo-forum-root .nuo-forum-boards-list [class*="desc"], .nuo-forum-root .nuo-forum-message-preview, .nuo-forum-root .nuo-forum-board-desc, .nuo-forum-root .nuo-forum-board-hero [class*="desc"] { color: #71767b !important; fill: #71767b !important; }

/* ==========================================
   3. 页面背景与容器黑化
   ========================================== */
.nuo-forum-root .nuo-forum-comments, .nuo-forum-root .nuo-forum-comment { background-color: #000000 !important; }
.nuo-forum-root .nuo-forum-boards-list, .nuo-forum-root .nuo-forum-board-detail, .nuo-forum-root .nuo-forum-messages-list, .nuo-forum-root .nuo-forum-profile, .nuo-forum-root .nuo-forum-me, .nuo-forum-root [class*="message"], .nuo-forum-root [class*="chat"] { background-color: #000000 !important; background: #000000 !important; }
.nuo-forum-root [class*="chat"][class*="bar"], .nuo-forum-root [class*="message"][class*="bar"], .nuo-forum-root [class*="footer"] { background-color: #000000 !important; border-top: 1px solid #2f3336 !important; }
.nuo-forum-root .nuo-forum-boards-list > div:first-child, .nuo-forum-root [class*="search"] { background-color: #000000 !important; }
.nuo-forum-root .nuo-forum-me div, .nuo-forum-root .nuo-forum-profile div, .nuo-forum-root .nuo-forum-board-card { background-color: #000000 !important; border-color: #2f3336 !important; }
.nuo-forum-root .nuo-forum-chrome-nav { background-color: #000000 !important; background-image: none !important; border-top: 1px solid #2f3336 !important; }

/* ==========================================
   4. 输入框胶囊化
   ========================================== */
.nuo-forum-root [class*="chat"] input, .nuo-forum-root [class*="chat"] textarea, .nuo-forum-root [class*="message"] input, .nuo-forum-root [class*="message"] textarea, .nuo-forum-root .nuo-forum-boards-list input { background-color: #202327 !important; color: #e7e9ea !important; border: none !important; border-radius: 9999px !important; padding-left: 16px !important; padding-right: 16px !important; }
.nuo-forum-root .nuo-forum-comment-input::-webkit-input-placeholder, .nuo-forum-root .nuo-forum-comment-input::placeholder { color: transparent !important; }
.nuo-forum-root .nuo-forum-comment-input:placeholder-shown { background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='150' height='20'%3E%3Ctext x='0' y='15' fill='%2371767b' font-size='14px' font-family='system-ui, sans-serif'%3E发布你的回复%3C/text%3E%3C/svg%3E") !important; background-repeat: no-repeat !important; background-position: 12px center !important; }

/* ==========================================
   5. 评论区骨架
   ========================================== */
.nuo-forum-root .nuo-forum-comments { padding-left: 0 !important; padding-right: 0 !important; }
.nuo-forum-root .nuo-forum-comments-header { padding-left: 16px !important; padding-right: 16px !important; border-bottom: 1px solid #2f3336 !important; }
.nuo-forum-root .nuo-forum-comment { margin: 0 !important; border-radius: 0 !important; padding: 12px 16px !important; border-bottom: 1px solid #2f3336 !important; }

/* ==========================================
   6. 全局头像强制正方切圆 (板块版主除外)
   ========================================== */
.nuo-forum-root [class*="avatar"],
.nuo-forum-root [class*="avatar"] img { 
    width: 40px !important; 
    height: 40px !important; 
    border-radius: 50% !important; 
    overflow: hidden !important; 
    object-fit: cover !important;
    flex-shrink: 0 !important;
}
/* 恢复板块头部（版主）的小头像尺寸 */
.nuo-forum-root .nuo-forum-board-card [class*="avatar"],
.nuo-forum-root .nuo-forum-board-card [class*="avatar"] img,
.nuo-forum-root .nuo-forum-board-hero [class*="avatar"],
.nuo-forum-root .nuo-forum-board-hero [class*="avatar"] img {
    width: 20px !important;
    height: 20px !important;
}

/* ==========================================
   7. 帖子紧凑排版与文字
   ========================================== */
.nuo-forum-root .nuo-forum-post {
    position: relative !important; display: block !important;
    padding: 12px 16px 34px 68px !important; margin: 0 !important; border-radius: 0 !important;
    border-bottom: 1px solid #2f3336 !important; background-color: #000000 !important; color: #e7e9ea !important;
}
.nuo-forum-root .nuo-forum-post:active, .nuo-forum-root .nuo-forum-post:hover { background-color: #080808 !important; }

.nuo-forum-root .nuo-forum-post-author-name {
    position: absolute !important; top: 12px !important; left: 68px !important;
    font-size: 15px !important; font-weight: 700 !important; line-height: 1.2 !important;
    white-space: nowrap !important; overflow: visible !important; opacity: 1 !important; color: #e7e9ea !important;
}
.nuo-forum-root .nuo-forum-post-author-name span { font-weight: 400 !important; margin-left: 4px !important; color: #71767b !important; }
.nuo-forum-root .nuo-forum-post-time {
    position: absolute !important; top: 12px !important; right: 16px !important;
    font-size: 14px !important; line-height: 1.2 !important; color: #71767b !important;
}
.nuo-forum-root .nuo-forum-post-title, .nuo-forum-root .nuo-forum-post-title *, .nuo-forum-root .nuo-forum-post-excerpt, .nuo-forum-root .nuo-forum-post-excerpt * {
    margin-top: 18px !important; margin-bottom: 0 !important;
    font-size: 15px !important; font-weight: 400 !important; line-height: 1.4 !important; display: block !important;
    color: #e7e9ea !important; opacity: 1 !important;
}

/* ==========================================
   8. 强制空间转移与推特平底匿名头像
   ========================================== */
.nuo-forum-root .nuo-forum-post [class*="avatar"] {
    position: absolute !important; 
    top: 12px !important; 
    left: 16px !important;
    margin: 0 !important;
    z-index: 2 !important; 
}

/* 针对完全没有头像的帖子补全 */
.nuo-forum-root .nuo-forum-post:not(:has([class*="avatar"]))::before,
.nuo-forum-root .nuo-forum-comment:not(:has([class*="avatar"]))::before {
    content: ''; position: absolute !important; top: 12px !important; left: 16px !important;
    width: 40px !important; height: 40px !important; border-radius: 50% !important; overflow: hidden !important;
    background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40'%3E%3Crect width='40' height='40' fill='%23333639'/%3E%3Ccircle cx='20' cy='14' r='7' fill='%2371767b'/%3E%3Cpath d='M6 40c0-9 6-15 14-15s14 6 14 15H6z' fill='%2371767b'/%3E%3C/svg%3E") !important; background-size: cover !important; z-index: 1 !important;
}
/* 针对虽然有头像元素，但是没有 img 标签的（比如匿名）强制覆盖 */
.nuo-forum-root [class*="avatar"]:not(:has(img)):not([style*="background"]) {
    background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40'%3E%3Crect width='40' height='40' fill='%23333639'/%3E%3Ccircle cx='20' cy='14' r='7' fill='%2371767b'/%3E%3Cpath d='M6 40c0-9 6-15 14-15s14 6 14 15H6z' fill='%2371767b'/%3E%3C/svg%3E") !important; 
    background-size: cover !important; 
    color: transparent !important; 
}

