  --overlay-bg: url("https://iili.io/CjSvF99.md.jpg") center/cover no-repeat fixed;
  --btn-icon-color: var(--accent);
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg-base: #0f0f0f;
    --bg-card: transparent;
    --text-main: #e8e8e8;
    --text-mute: #999999;
    --accent: #aaaaaa;
