value.customCss:
@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@300;400;500;700&display=swap');

/* ══════════════════════
   ROOT
══════════════════════ */
.xt-root {
  --xt-bg:         #0f0f0f;
  --xt-text:       #e0e0e0;
  --xt-text-sub:   #888888;
  --xt-text-muted: #555555;
  --xt-accent:     #909090;
  --xt-accent-bg:  rgba(255,255,255,0.05);
  --xt-border:     #2e2e2e;
  --xt-radius:     18px;
  --xt-radius-sm:  11px;
  --xt-font:       'Noto Sans SC','PingFang SC','Hiragino Sans GB',sans-serif;
  --xt-anim-duration: 0.28s;
  --pink:          #888888;
  --pink-bg:       #1f1f1f;
  --pink-border:   #3a3a3a;
  --pink-text:     #bbbbbb;
  background: var(--xt-bg);
  padding: 0;
  font-size: 13px;
  line-height: 1.5;
}
.xt-content { padding: 14px 13px 14px; }

/* ══════════════════════
   CARD 通用
══════════════════════ */
.xt-card {
  background: #1a1a1a !important;
  border: 1.5px solid #2a2a2a !important;
  border-radius: 16px !important;
  padding: 0 !important;
  margin-bottom: 10px !important;
  box-shadow: 0 2px 12px rgba(255,255,255,0.03) !important;
  overflow: hidden !important;
}
.xt-card:hover { box-shadow: 0 4px 18px rgba(255,255,255,0.08) !important; transform: none !important; }
.xt-card-title {
  font-size: 10px !important;
  font-weight: 700 !important;
  color: #555555 !important;
  letter-spacing: 1.2px !important;
  text-transform: uppercase !important;
  padding: 11px 14px 2px !important;
  margin: 0 !important;
  display: block !important;
}

/* ══════════════════════
   最近搜索区
   设计：带标题的独立白卡
   四行搜索词 + 展开心声
══════════════════════ */

/* 四个搜索词共同外包一个白卡效果
   用 search1 第一行的 ::before 做卡片标题 */
.xt-text-search1 {
  margin-top: 0 !important;
  border-radius: 16px 16px 0 0 !important;
  border-bottom: 1px solid #212121 !important;
  padding-top: 10px !important;
}
.xt-text-search1::before {
  content: "🔍  最近搜索" !important;
  display: block !important;
  font-size: 10px !important;
  font-weight: 700 !important;
  color: #555555 !important;
  letter-spacing: 1.2px !important;
  text-transform: uppercase !important;
  margin-bottom: 8px !important;
  padding: 0 !important;
}

/* 四个搜索词的共同样式 */
.xt-text-search1,
.xt-text-search2,
.xt-text-search3,
.xt-text-search4 {
  display: block !important;
  background: #1a1a1a !important;
  border-left: 1.5px solid #2a2a2a !important;
  border-right: 1.5px solid #2a2a2a !important;
  border-top: none !important;
  border-bottom: 1px solid #212121 !important;
  border-radius: 0 !important;
  padding: 11px 40px 11px 16px !important;
  margin: 0 !important;
  font-size: 13.5px !important;
  font-weight: 400 !important;
  color: #e0e0e0 !important;
  font-style: normal !important;
  cursor: pointer !important;
  position: relative !important;
  transition: background 0.15s !important;
}
/* 左侧搜索图标 */
.xt-text-search1::after,
.xt-text-search2::after,
.xt-text-search3::after,
.xt-text-search4::after {
  content: "›" !important;
  position: absolute !important;
  right: 15px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  font-size: 20px !important;
  color: #444444 !important;
  line-height: 1 !important;
  transition: color 0.15s, transform 0.2s !important;
  font-style: normal !important;
}
